  static List<List<int>> parseLayout(String csv) {
    List<List<int>> layout = [];
    List<String> lines = csv.trim().split('\n');
    
    for (var line in lines) {
      if (line.trim().isEmpty) continue;
      
      List<int> row = [];
      List<String> cells = line.split(',');
      
      for (var cell in cells) {
        String cleaned = cell.trim();
        if (cleaned.isEmpty) {
          row.add(0); // Treat empty as aisle or void
        } else {
          try {
             // The format is like "(B7)1" or just "0" or "4"
             // Take the last character as the type
             String typeChar = cleaned.length > 0 ? cleaned[cleaned.length - 1] : '0';
             // If the last char is not a digit (e.g. some malformed data), fallback
             int? type = int.tryParse(typeChar);
             row.add(type ?? 0);
          } catch (e) {
            row.add(0);
          }
        }
      }
      layout.add(row);
    }
    return layout;
  }

